from text import truncate


def test_short_value_is_kept():
    assert truncate("hi", 10) == "hi"


def test_long_value_gets_dots():
    assert truncate("a long title for a card", 10).endswith("...")


def test_truncated_value_ends_with_dots_and_keeps_prefix():
    result = truncate("abcdefghijklmnopqrstuvwxyz", 10)
    assert result.endswith("...")
    assert result.startswith("abcdefg")


def test_value_shorter_than_width_is_unchanged():
    assert truncate("abc", 10) == "abc"

